"""Stage 0 C code generator.

M0 has no syntax yet, so every program it accepts is the empty program,
and the C it produces is just an empty `main`.
"""


def generate() -> str:
    return "\n".join([
        "// Generated by the Vela stage 0 compiler. Do not edit.",
        '#include "vela_rt.h"',
        "",
        "int main(void) {",
        "    return 0;",
        "}",
        "",
    ])
